seen=set(); active=set()
def visit(key):
    assert key not in active, 'Ciclo de dependência: '+key
    if key in seen:return
    active.add(key)
    for d in bykey[key]['deps']:visit(d)
    active.remove(key);seen.add(key)
for t in tasks:visit(t['key'])

